class Solution { fun maximumBeauty(items:Array<IntArray>,queries:IntArray):IntArray{items.sortBy{it[0]};for(i in 1 until items.size)items[i][1]=maxOf(items[i][1],items[i-1][1]);return IntArray(queries.size){q->var left=0;var right=items.size;while(left<right){val middle=(left+right)/2;if(items[middle][0]<=queries[q])left=middle+1 else right=middle};if(left==0)0 else items[left-1][1]}} }
